using System;
class Naval321Checks {
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Main(){var s=NavalShipDefinition.Novik;var points=NavalRaisedBridge.Ascent(s);Check((points[0].Z-NavalRaisedBridge.Center(s))*s.Scale>3.5f,"Bridge approach starts outside front wall");Check(Math.Abs(points[1].X*s.Scale-2.1f)<.01f&&points[1].Y==NavalRaisedBridge.Base(s),"Cross to stair lane on bottom landing");Check((points[1].Z-points[2].Z)*s.Scale>2,"Approach along stair axis, not through side treads");Check(2.1f-.8f>.7f,"Capsule head clears upper floor edge");Check(2.1f+.8f<3.2f,"Actual stair entrance clears front wall");Check(3.3f-2.2f>.8f+.2f,"Top landing clears back armour");foreach(var p in points)Check(NavalCrewDeckSafety.Inside(p.X,p.Z,s,.8f),"Bridge path remains inside vessel");
 var positions=new System.Collections.Generic.List<NavalWalkPoint>();for(int i=0;i<s.CrewCount;i++){var post=NavalShipDefinition.StandbyPost(s,i);Check(NavalCrewDeckSafety.Inside(post.x,post.z,s,.8f),"Distributed standby remains inside hull");foreach(var other in positions){double dx=(post.x-other.X)*s.Scale,dz=(post.z-other.Z)*s.Scale;Check(dx*dx+dz*dz>3*3,"Initial watch positions do not pile up");}positions.Add(new NavalWalkPoint(post.x,post.y,post.z));}
 float r=NavalArmorMath.InternalBlastWorldRadius(5.2f,2.97f);Check(r>1&&r<1.2f,"203-class AP burst is local rather than six-metre hole");foreach(float scale in new[]{2f,4f,6f,s.Scale}){float local=r/scale;Check(Math.Abs(local*scale-r)<.001,"AP destruction independent of target scale");}Check(NavalArmorMath.InternalBlastWorldRadius(7.8f,7)<1.6f,"Heavy AP radius bounded");Console.WriteLine("PASS: axial bridge entry, safe landings, twelve separated crew posts and metre-based AP bursts.");}
}
